/* LD_PRELOAD shim: remap a single TCP bind port for THIS process only.
 * Purpose: the console netreceive in the challenge patch binds port 4562,
 * but another (root-owned) process already squats 4562 system-wide. This
 * shim rewrites ONLY the bind() port number 4562 -> $BIND_REMAP_TO for our
 * own pd process, so we can run the genuine patch on a private port.
 * It changes transport plumbing only; no challenge logic/object is touched.
 */
#define _GNU_SOURCE
#include <dlfcn.h>
#include <netinet/in.h>
#include <sys/socket.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

typedef int (*bind_fn)(int, const struct sockaddr *, socklen_t);

static int from_port(void){
    const char *e = getenv("BIND_REMAP_FROM");
    return e ? atoi(e) : 4562;
}
static int to_port(void){
    const char *e = getenv("BIND_REMAP_TO");
    return e ? atoi(e) : 24562;
}

int bind(int sockfd, const struct sockaddr *addr, socklen_t addrlen){
    static bind_fn real = 0;
    if(!real) real = (bind_fn)dlsym(RTLD_NEXT, "bind");
    if(addr){
        int fp = from_port();
        if(addr->sa_family == AF_INET && addrlen >= sizeof(struct sockaddr_in)){
            struct sockaddr_in a4;
            memcpy(&a4, addr, sizeof(a4));
            if(ntohs(a4.sin_port) == fp){
                a4.sin_port = htons(to_port());
                return real(sockfd, (struct sockaddr*)&a4, sizeof(a4));
            }
        } else if(addr->sa_family == AF_INET6 && addrlen >= sizeof(struct sockaddr_in6)){
            struct sockaddr_in6 a6;
            memcpy(&a6, addr, sizeof(a6));
            if(ntohs(a6.sin6_port) == fp){
                a6.sin6_port = htons(to_port());
                return real(sockfd, (struct sockaddr*)&a6, sizeof(a6));
            }
        }
    }
    return real(sockfd, addr, addrlen);
}

