#!/usr/bin/env python3
# Collect (seed -> 42-char render) pairs from the live csirac console.
# Does full setup once, then loops: DECK ; EXPORT <seed> ; capturing each render.
import socket, time, threading, argparse, re, json, sys

PROMPT=b"CSIRAC> "

def clock(ctrl_port,val):
    try:
        c=socket.create_connection(("127.0.0.1",ctrl_port),timeout=5)
        c.sendall(bytes([val])); time.sleep(0.2); c.close(); return True
    except Exception as e:
        print("clock err",e,flush=True); return False

def printable(b):
    return ''.join(chr(x) if 32<=x<127 else ('\n' if x==10 else '.') for x in b)

class Reader:
    def __init__(self,s):
        self.s=s; self.buf=bytearray(); self.lock=threading.Lock(); self.alive=True
        threading.Thread(target=self.run,daemon=True).start()
    def run(self):
        while self.alive:
            try: d=self.s.recv(8192)
            except socket.timeout: continue
            except Exception: break
            if not d: self.alive=False; break
            with self.lock: self.buf.extend(d)
    def snap(self):
        with self.lock: return bytes(self.buf)

def send_wait(s,r,cmd,base,timeout):
    s.sendall((cmd+"\n").encode())
    t0=time.time()
    while time.time()-t0<timeout:
        snap=r.snap(); tail=snap[base:]
        if tail.count(PROMPT)>=1:
            return len(snap), tail
        if not r.alive: return len(snap), tail
        time.sleep(0.3)
    return len(r.snap()), r.snap()[base:]

def extract_render(reply_bytes):
    # reply looks like: " transport rolling\n\n rendering stem ...\n\n <42chars>\n\nCSIRAC> "
    txt=reply_bytes.decode('latin1')
    # take line that is exactly 42 printable chars (no CSIRAC, not a status word)
    for line in txt.split("\n"):
        ln=line.strip()
        if len(ln)==42:
            return ln
    # fallback: longest line
    cand=sorted((l.strip() for l in txt.split("\n")), key=len, reverse=True)
    return cand[0] if cand else ""

def main():
